    )
}

did_cluster_formula <- ~ cz_id^aewr_region_id

did_model <- function(data, outcome, controls = FALSE) {
  control_terms <- if (controls) {
    " + ln_pop_census + emp_pop_ratio"
  } else {
    ""
  }
  formula <- stats::as.formula(paste0(
    outcome,
    " ~ aewr_cz_p25_l1 * post",
    control_terms,
    " | county_fips + year"
  ))
  fixest::feols(
    formula,
    data = data,
    vcov = did_cluster_formula,
    notes = FALSE
  )
}

